import { test as base } from '@playwright/test'

import { resolveBinary, StructurizrSiteCli } from './cli.ts'
import { expect } from './matchers.ts'
import { Sandbox } from './sandbox.ts'
import { GeneratedSite } from './site.ts'

interface Fixtures {
  /** Per-test scratch directory; removed when the test finishes. */
  sandbox: Sandbox
  /** The CLI under test, running in the sandbox. */
  cli: StructurizrSiteCli
  /** A site generated by the CLI and served like a static host would. */
  site: GeneratedSite
}

export const test = base.extend<Fixtures>({
  // Playwright requires the fixtures argument to be a destructuring pattern, even when empty.
  // eslint-disable-next-line no-empty-pattern
  sandbox: async ({}, use) => {
    const sandbox = await Sandbox.create()
    await use(sandbox)
    await sandbox.dispose()
  },

  cli: async ({ sandbox }, use) => {
    await use(new StructurizrSiteCli(resolveBinary(), sandbox))
  },

  site: async ({ sandbox }, use) => {
    const site = new GeneratedSite(sandbox, resolveBinary())
    await use(site)
    await site.dispose()
  },
})

export { expect }
